// QueryDrinks queries the drinks edge of a Brand.
func (c *BrandClient) QueryDrinks(_m *Brand) *DrinkQuery {
	query := (&DrinkClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(brand.Table, brand.FieldID, id),
			sqlgraph.To(drink.Table, drink.FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, brand.DrinksTable, brand.DrinksColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

