// QueryDrinkFlavours queries the drink_flavours edge of a Flavour.
func (c *FlavourClient) QueryDrinkFlavours(_m *Flavour) *DrinkFlavourQuery {
	query := (&DrinkFlavourClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(flavour.Table, flavour.FieldID, id),
			sqlgraph.To(drinkflavour.Table, drinkflavour.FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, flavour.DrinkFlavoursTable, flavour.DrinkFlavoursColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

